from pathlib import Path
import re
TOKEN = re.compile(r"`((?:pages|samples)/[^`\s:]+):(\d+)(?:-(\d+))?`")
URL = re.compile(r"https?://[^\s)`]+")
errs=[]
for name in ["04-security-model.md","05-configuration-model.md","06-containers-conf-reference.md"]:
    t=Path(name).read_text(); lines=t.splitlines()
    # shape
    if not re.match(r"^# \d\d — \S", lines[0]): errs.append(f"{name}: bad title")
    heads=[l for l in lines if l.startswith("## ")]
    if len(heads)<3 or heads[-2:]!=["## Pitfalls","## Sources"]: errs.append(f"{name}: bad heads {heads[-2:]}")
    # citations
    for p,a,b in TOKEN.findall(t):
        f=Path(p)
        if not f.is_file(): errs.append(f"{name}: missing {p}"); continue
        n=len(f.read_text().splitlines()); lo,hi=int(a),int(b or a)
        if lo<1 or hi<lo or hi>n: errs.append(f"{name}: OOR {p}:{a}-{b} (n={n})")
    for bad in ("TBD","TODO","PLACEHOLDER","unverified claim"):
        if bad in t: errs.append(f"{name}: placeholder {bad}")
    # fences
    i=0
    while i<len(lines):
        if not lines[i].startswith("```"): i+=1; continue
        lang=lines[i][3:].strip(); head=lines[i-1] if i else ""; j=i+1; body=[]
        while j<len(lines) and not lines[j].startswith("```"): body.append(lines[j]); j+=1
        if not lang: errs.append(f"{name}:{i+1}: no lang")
        if len(body)>25: errs.append(f"{name}:{i+1}: {len(body)} body lines")
        toks=TOKEN.findall(head)
        if len(toks)>1: errs.append(f"{name}:{i+1}: multi token in head")
        if toks:
            p,a,b=toks[0]; f=Path(p)
            if f.is_file():
                src=f.read_text().splitlines(); lo,hi=int(a),int(b or a)
                want=[l.rstrip() for l in src[lo-1:hi] if l.strip()!="…"]
                got=[l.rstrip() for l in body if l.strip()!="…"]
                if want!=got:
                    errs.append(f"{name}:{i+1}: NOT VERBATIM {p}:{a}-{b}")
                    for k,(w,g) in enumerate(zip(want,got)):
                        if w!=g: errs.append(f"   line {k}: WANT {w!r}\n          GOT  {g!r}")
                    if len(want)!=len(got): errs.append(f"   len want={len(want)} got={len(got)}")
        elif not URL.search(head) and not re.search(r"\bderived\b|\bcálculo\b|\bsaída\b|\bcomputado\b",head,re.I):
            errs.append(f"{name}:{i+1}: head lacks source/derived: {head!r}")
        i=j+1
    print(f"{name}: {len(lines)} lines, {len(heads)} sections")
print("\nERRORS:" if errs else "\nALL CHECKS PASSED")
for e in errs: print(e)
PY)
